  const week = /^\d{4}-\d{2}-\d{2}$/.test(String(req.week_start || '')) && new Date(req.week_start + 'T12:00:00Z').getUTCDay() === 1 && req.week_start >= ideasMonday(now) ? req.week_start : ideasMonday(now + 7 * 86400000);
