    req.channel = typeof x.channel === 'string' ? x.channel : '';
    req.schedule_at = typeof x.schedule_at === 'string' ? x.schedule_at.slice(0, 40) : '';
    if (typeof x.caption === 'string') req.caption = x.caption.slice(0, 3000);
