function liConfirmHash(parts) { let h = 0x811c9dc5; const s = parts.join('\u0001'); for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16).padStart(8, '0'); }

function liLabel(state) { return ({ recomendado: 'Recomendado', aprobacion_pendiente: 'Pendiente de aprobación', en_lista: 'En lista (sin contactar)', en_campana: 'En campaña (conexión)', conexion: 'Conexión aceptada', mensaje: 'Mensaje enviado', followup: 'Follow-up enviado', respondio: 'Respondió', rechazo: 'Rechazó', detenido: 'Detenido', error: 'Error' })[state] || String(state || '—'); }

