function liStrip(s) { return String(s == null ? '' : s).normalize('NFD').replace(/[̀-ͯ]/g, ''); }

function linkedinOverview(cands, nowMs) {
  const list = Array.isArray(cands) ? cands : [];
  const counts = { pendiente: 0, en_lista: 0, en_campana: 0, conexion: 0, mensaje: 0, followup: 0, respondio: 0, rechazo: 0, error: 0 };
  const rows = [];
