  const p = h[h.length - 1];
  return { subject: p.subject || '', body: p.body || '', score: typeof p.score === 'number' ? p.score : null, at: p.at || null, by: p.by || null, reason: p.reason || null, versions: h.length };
}

function oaReads(req, sb) {
