  push('pieza_lista', 3, ready.length === 1 ? '1 pieza lista para programar' : ready.length + ' piezas listas para programar', 'Redes → Taller', ready, (p) => p.updated_at || p.created_at, '/ops?view=taller', ready.map((p) => p.topic));
