    req.text = typeof x.text === 'string' ? x.text.trim().slice(0, 500) : '';
  }
  if (action === 'pause_set') {
    if (typeof x.paused !== 'boolean') return { ok: false, error: 'paused_invalido', message: 'paused (true/false) es obligatorio.' };
    req.paused = x.paused;
    if (x.resume_at != null && x.resume_at !== '') {
      const ra = Date.parse(String(x.resume_at));
      if (!Number.isFinite(ra)) return { ok: false, error: 'fecha_invalida', message: 'resume_at debe ser una fecha válida.' };
      req.resume_at = new Date(ra).toISOString();
    }
  }
  if (action === 'idea_decide') {
    if (!oaIsUuid(x.idea_id)) return { ok: false, error: 'idea_id_invalido', message: 'idea_id (uuid de la idea) es obligatorio.' };
    req.idea_id = String(x.idea_id).toLowerCase();
    req.decision = String(x.decision || '').toLowerCase();
    if (!['approve', 'change', 'discard', 'move'].includes(req.decision)) return { ok: false, error: 'decision_invalida', message: 'decision: approve | change | discard | move.' };
    req.text = typeof x.text === 'string' ? x.text.trim().slice(0, 1000) : '';
    req.chips = Array.isArray(x.chips) ? x.chips.filter((c) => typeof c === 'string').map((c) => c.trim().slice(0, 40)).filter(Boolean).slice(0, 6) : [];
    req.test = x.test === true;
    req.week_start = typeof x.week_start === 'string' ? x.week_start.trim().slice(0, 10) : '';
  }
  if (action === 'idea_mine') {
    req.title = typeof x.title === 'string' ? x.title.trim().slice(0, 200) : '';
    req.channel = String(x.channel || '');
    req.format = String(x.format || '');
    req.test = x.test === true;
    req.text = typeof x.text === 'string' ? x.text.trim().slice(0, 400) : '';
    req.week_start = typeof x.week_start === 'string' ? x.week_start.trim().slice(0, 10) : '';
    if (req.title.length < 5) return { ok: false, error: 'falta_titulo', message: 'Escribe tu idea en una frase (mínimo 5 caracteres).' };
  }
  if (action.startsWith('taller_')) {
    if (!oaIsUuid(x.piece_id)) return { ok: false, error: 'piece_id_invalido', message: 'piece_id (uuid de la pieza) es obligatorio.' };
    req.piece_id = String(x.piece_id).toLowerCase();
    req.test = x.test === true;
    req.text = typeof x.text === 'string' ? x.text.trim().slice(0, 2000) : '';
    req.scope = typeof x.scope === 'string' && /^(global|lamina [0-9]{1,2})$/.test(x.scope) ? x.scope : 'global';
    req.channel = typeof x.channel === 'string' ? x.channel : '';
    req.schedule_at = typeof x.schedule_at === 'string' ? x.schedule_at.slice(0, 40) : '';
    if (typeof x.caption === 'string') req.caption = x.caption.slice(0, 3000);
    if (action === 'taller_schedule' && !Number.isFinite(Date.parse(req.schedule_at))) return { ok: false, error: 'falta_fecha', message: 'schedule_at (fecha y hora ISO) es obligatorio.' };
    if (action === 'taller_add_version') {
      if (!Array.isArray(x.assets) || x.assets.length > 10) return { ok: false, error: 'assets_invalidos', message: 'assets: lista de 0 a 10 archivos {path, w, h}.' };
      req.assets = x.assets.map((a) => ({ path: String((a && a.path) || '').slice(0, 200), w: Number(a && a.w) || null, h: Number(a && a.h) || null, label: typeof (a && a.label) === 'string' ? a.label.slice(0, 80) : null }));
      req.qa = x.qa && typeof x.qa === 'object' ? x.qa : {};
      req.cost_credits = Number(x.cost_credits) || 0;
      req.created_by = typeof x.created_by === 'string' ? x.created_by.slice(0, 60) : 'Claude';
      req.notes = typeof x.notes === 'string' ? x.notes.slice(0, 1000) : null;
      req.version_no = Number(x.version_no) || null;
      req.attempts = Number(x.attempts) || 0;
    }
  }
  if (action.startsWith('prep_')) {
    if (!oaIsUuid(x.candidate_id)) return { ok: false, error: 'candidate_id_invalido', message: 'candidate_id (uuid del prospecto) es obligatorio.' };
    req.candidate_id = String(x.candidate_id).toLowerCase();
    if (action === 'prep_li_sent') {
      req.kind = String(x.kind || '').toLowerCase();
      if (!['invitation', 'connected', 'message', 'reply', 'closed'].includes(req.kind)) return { ok: false, error: 'kind_invalido', message: 'kind: invitation | connected | message | reply | closed.' };
      req.text = typeof x.text === 'string' ? x.text.trim().slice(0, 1500) : '';
    }
    if (action === 'prep_hold' && String(req.reason || '').length < 8) return { ok: false, error: 'falta_razon', message: 'EN ESPERA exige una razón comercial explícita (≥ 8 caracteres).' };
    if (action === 'prep_contact') {
      req.email = typeof x.email === 'string' ? x.email.trim().toLowerCase().slice(0, 200) : '';
      req.linkedin = typeof x.linkedin === 'string' ? x.linkedin.trim().slice(0, 300) : '';
      if (!req.email && !req.linkedin) return { ok: false, error: 'sin_dato', message: 'Pega un correo o un enlace de LinkedIn.' };
    }
  }
  if (action.startsWith('linkedin_')) {
    if (!oaIsUuid(x.candidate_id)) return { ok: false, error: 'candidate_id_invalido', message: 'candidate_id (uuid del prospecto) es obligatorio.' };
    req.candidate_id = String(x.candidate_id).toLowerCase();
  }
  if (action.startsWith('content_')) {
    if (!oaIsUuid(x.piece_id)) return { ok: false, error: 'piece_id_invalido', message: 'piece_id (uuid de la pieza) es obligatorio.' };
    req.piece_id = String(x.piece_id).toLowerCase();
  }
  return { ok: true, req };
}

function v3Age(ms, nowMs) {
  const t = Number.isFinite(ms) ? Math.max(0, nowMs - ms) : 0;
  const h = Math.floor(t / 3600000), dd = Math.floor(h / 24);
  return { text: dd >= 1 ? 'hace ' + dd + ' d' : h >= 1 ? 'hace ' + h + ' h' : 'hace minutos', tone: h < 24 ? 'fresh' : h < 72 ? 'warn' : 'old' };
}

function v3GateOverride(out, state) {
  const p = v3Pause(state);
  if (!p.paused) return out;
  return { ...(out || {}), mode: 'skip', paused: true, reason: 'Pausa general activa' + (p.reason ? ' («' + p.reason + '»)' : '') + ': no se investiga ni se crea nada hasta que Christian reanude desde /ops.' };
}

function v3Inbox(x) {
  const now = Number(x && x.now) || Date.now();
  const items = [];
  const isTestName = (s) => /\bTEST\b/.test(String(s || ''));
  const oldest = (arr, f) => arr.reduce((m, r) => { const v = Date.parse(f(r)); return Number.isFinite(v) && v < m ? v : m; }, Infinity);
  const push = (kind, prio, title, from, list, f, href, names) => {
    if (!list.length) return;
    const o = oldest(list, f);
    const age = v3Age(Number.isFinite(o) ? o : now, now);
    items.push({ kind, prio, count: list.length, title, from, age: age.text, tone: age.tone, href, examples: (names || []).filter(Boolean).slice(0, 3) });
  };
  const msgs = Array.isArray(x && x.messages) ? x.messages : [];
  const drafts = msgs.filter((m) => m.direction === 'outbound' && m.status === 'draft' && !isTestName(m.company_name));
  push('correo', 1, drafts.length === 1 ? '1 correo por aprobar' : drafts.length + ' correos por aprobar', 'Prospección y correo', drafts, (m) => m.created_at, '/ops?view=aprobaciones&filter=correos', drafts.map((m) => m.company_name));
  const ideas = (Array.isArray(x && x.ideas) ? x.ideas : []).filter((i) => !i.is_test && i.status === 'proposed');
  push('idea', 2, ideas.length === 1 ? '1 idea por decidir' : ideas.length + ' ideas por decidir', 'Redes → Ideas', ideas, (i) => i.created_at, '/ops?view=ideas', ideas.map((i) => i.title));
  const pieces = (Array.isArray(x && x.pieces) ? x.pieces : []).filter((p) => !p.is_test && ['para_revisar', 'lista', 'programada_pendiente_de_clic'].includes(p.taller_status));
  const rev = pieces.filter((p) => p.taller_status === 'para_revisar'), ready = pieces.filter((p) => p.taller_status === 'lista'), click = pieces.filter((p) => p.taller_status === 'programada_pendiente_de_clic');
  push('pieza', 3, rev.length === 1 ? '1 pieza para revisar' : rev.length + ' piezas para revisar', 'Redes → Taller', rev, (p) => p.updated_at || p.created_at, '/ops?view=taller', rev.map((p) => p.topic));
  push('pieza_lista', 3, ready.length === 1 ? '1 pieza lista para programar' : ready.length + ' piezas listas para programar', 'Redes → Taller', ready, (p) => p.updated_at || p.created_at, '/ops?view=taller', ready.map((p) => p.topic));
  push('pieza_clic', 3, click.length === 1 ? '1 carrusel espera tu último clic en GHL' : click.length + ' carruseles esperan tu último clic en GHL', 'Redes → Taller', click, (p) => p.updated_at || p.created_at, '/ops?view=taller', click.map((p) => p.topic));
  const att = Array.isArray(x && x.attention) ? x.attention : [];
  const g = (k) => att.find((a) => a.key === k);
  const rep = g('replies');
  if (rep) items.push({ kind: 'respuesta', prio: 4, count: rep.count, title: rep.count === 1 ? '1 respuesta por contestar' : rep.count + ' respuestas por contestar', from: 'Prospección y correo', age: '', tone: 'warn', href: '/ops?view=outreach', examples: rep.items.slice(0, 3).map((s) => String(s).split(' · ')[0]) });
  const find = g('prep_find');
  if (find) items.push({ kind: 'contacto', prio: 5, count: find.count, title: find.count === 1 ? '1 contacto por pegar' : find.count + ' contactos por pegar', from: 'Prospección y correo', age: '', tone: 'fresh', href: '/ops?view=control', examples: find.items.slice(0, 3) });
  const al = (Array.isArray(x && x.alerts) ? x.alerts : []).filter((a) => a.status === 'open' && !String(a.alert_key || '').startsWith('_') && ['critical', 'high'].includes(a.severity));
  push('alerta', 6, al.length === 1 ? '1 alerta pide tu atención' : al.length + ' alertas piden tu atención', 'Sistema', al, (a) => a.first_seen_at, '/ops?view=alertas', al.map((a) => a.title));
  // Fase 7: reuniones de hoy (reservas del sitio). No son decisiones, pero van arriba para no perderlas.
  const tz = (x && x.tz) || 'America/Santiago';
  const today = new Date(now).toLocaleDateString('en-CA', { timeZone: tz });
  const meet = (Array.isArray(x && x.meetings) ? x.meetings : []).filter((m) => m.meeting_start && new Date(Date.parse(m.meeting_start)).toLocaleDateString('en-CA', { timeZone: tz }) === today);
  if (meet.length) items.push({ kind: 'reunion', prio: 0, count: meet.length, title: meet.length === 1 ? '1 reunión hoy' : meet.length + ' reuniones hoy', from: 'Reservas del sitio', age: '', tone: 'fresh', href: '/ops?view=hoy#mi-semana', examples: meet.map((m) => new Date(Date.parse(m.meeting_start)).toLocaleTimeString('es-CL', { timeZone: tz, hour: '2-digit', minute: '2-digit', hour12: false }) + ' · ' + ([m.name, m.company].filter(Boolean).join(' · ') || 'Reunión')).slice(0, 3) });
  const ap = (x && x.approvals) || {};
  if (Number(ap.linkedin) > 0) items.push({ kind: 'linkedin', prio: 7, count: Number(ap.linkedin), title: Number(ap.linkedin) === 1 ? '1 alta de LinkedIn por aprobar' : ap.linkedin + ' altas de LinkedIn por aprobar', from: 'Prospección y correo', age: '', tone: 'fresh', href: '/ops?view=aprobaciones&filter=linkedin', examples: [] });
  if (Number(ap.content) > 0) items.push({ kind: 'publicacion', prio: 8, count: Number(ap.content), title: Number(ap.content) === 1 ? '1 publicación en revisión (GHL)' : ap.content + ' publicaciones en revisión (GHL)', from: 'Redes', age: '', tone: 'fresh', href: '/ops?view=aprobaciones&filter=contenido', examples: [] });
  items.sort((a, b) => a.prio - b.prio);
  return { items, total: items.reduce((s, i) => s + i.count, 0) };
}

function v3Pause(state) {
  const s = state && typeof state === 'object' ? state : {};
  return { paused: s.global_pause === true, reason: s.reason ? String(s.reason).slice(0, 200) : null, since: s.paused_at || null, by: s.paused_by || null, resume_at: s.resume_at || null };
}

function v3PausePlan(req, state, outreach, nowMs, by) {
  const s = state && typeof state === 'object' ? state : null;
  if (!s) return { error: 'sin_estado', message: 'No encontré el estado del sistema (system_state). No se hizo nada.' };
  const nowIso = new Date(nowMs).toISOString();
  const cur = s.global_pause === true;
  if (req.paused === cur) return { resp: { ok: true, status: cur ? 'already_paused' : 'already_running', paused: cur, message: cur ? 'Ya estaba en pausa.' : 'El sistema ya estaba funcionando.' }, writes: [] };
  const meta = { ...(s.meta || {}) };
  if (req.paused) {
    meta.last_pause = { at: nowIso, by, reason: req.reason || null };
    return { resp: { ok: true, status: 'paused', paused: true, message: 'PAUSA GENERAL activa. Se detuvieron: envío de correos, seguimientos, radar, preparación de contactos, producción y generación de medios. Lo ya programado en GHL NO se retiene.' },
      writes: [{ method: 'PATCH', path: 'system_state?id=eq.1&global_pause=eq.false', body: { global_pause: true, reason: req.reason || null, paused_at: nowIso, paused_by: by, resume_at: req.resume_at || null, meta, updated_at: nowIso }, prefer: 'return=representation', check_rows: true, check_message: 'No pude activar la pausa: el estado cambió mientras tanto. Recarga y vuelve a intentarlo.' }] };
  }
  const restore = meta.prev_outreach_paused === true;
  meta.last_resume = { at: nowIso, by };
  return { resp: { ok: true, status: 'resumed', paused: false, message: restore ? 'Sistema reanudado. Ojo: el envío de correos ya estaba en pausa antes y sigue así.' : 'Sistema reanudado: todo vuelve a funcionar como antes de la pausa.' },
    writes: [{ method: 'PATCH', path: 'system_state?id=eq.1&global_pause=eq.true', body: { global_pause: false, reason: null, paused_at: null, paused_by: null, resume_at: null, meta, updated_at: nowIso }, prefer: 'return=representation', check_rows: true, check_message: 'No pude reanudar: el estado cambió mientras tanto. Recarga y vuelve a intentarlo.' }] };
}

function ideasAddDays(day, n) {
  const d = new Date(String(day) + 'T12:00:00Z');
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
}

function ideasConfig() {
  return {
    min_score: 70, max_total: 12, caps: { instagram: 7, linkedin_page: 4, linkedin_profile: 3 }, dedupe_weeks: 4,
    channels: ['instagram', 'linkedin_page', 'linkedin_profile'], formats: ['texto', 'imagen', 'carrusel', 'demo', 'reel', 'historia'],
    objectives: ['alcance', 'autoridad', 'conversaciones', 'leads', 'recurso', 'servicio', 'educar'],
    metrics: ['reach', 'watch_time', 'saves', 'profile_visits', 'intent_comments', 'dms', 'leads'], efforts: ['bajo', 'medio', 'alto'],
    evidence_types: ['source', 'intel', 'metric', 'resource'],
  };
}

function ideasDeadline(idea, nowMs, tz) {
  const zone = tz || 'America/Santiago';
  const need = ({ bajo: 1, medio: 2, alto: 3 }[String((idea && idea.effort) || '')] || 2) + (ideasLane(idea && idea.format) === 'pc' ? 1 : 0);
  const closing = ideasAddDays(String((idea && idea.week_start) || ideasMonday(nowMs + 7 * 86400000, zone)), -3);
  const local = new Date(new Date(nowMs).toLocaleString('en-US', { timeZone: zone }));
  const today = local.getFullYear() + '-' + String(local.getMonth() + 1).padStart(2, '0') + '-' + String(local.getDate()).padStart(2, '0');
  let left = 0;
  for (let day = today, k = 0; day <= closing && k < 60; day = ideasAddDays(day, 1), k++) {
    const dow = new Date(day + 'T12:00:00Z').getUTCDay();
    if (dow === 0 || dow === 6) continue;
    if (day === today && local.getHours() >= 12) continue;
    left++;
  }
  const state = left >= need + 1 ? 'alcanza' : left === need ? 'justo' : 'no_alcanza';
  return { state, label: { alcanza: 'Alcanza', justo: 'Justo', no_alcanza: 'No alcanza' }[state], left, need, closing };
}

function ideasDecidePlan(req, idea, ctx) {
  const now = Number(ctx && ctx.now) || Date.now();
  if (!idea) return { error: 'idea_no_encontrada', message: 'No encontré esa idea.' };
  if (idea.is_test && !(ctx && ctx.allow_test)) return { error: 'idea_test', message: 'Esa idea es de prueba.' };
  const nowIso = new Date(now).toISOString();
  const by = (ctx && ctx.by) || 'Christian via /ops';
  const hist = (what, extra) => (Array.isArray(idea.history) ? idea.history : []).concat([{ at: nowIso, by, what, ...(extra || {}) }]).slice(-20);
  const guard = (states) => 'content_ideas?id=eq.' + idea.id + '&status=in.(' + states.join(',') + ')';
  const row = (body, states, msg) => ({ method: 'PATCH', path: guard(states), body: { ...body, updated_at: nowIso }, prefer: 'return=representation', check_rows: true, check_message: msg || 'La idea cambió mientras tanto. Recarga.' });
  const d = req.decision;
  if (d === 'approve') {
    if (idea.status === 'approved') return { resp: { ok: true, status: 'already_approved', message: 'Ya estaba aprobada.' }, writes: [] };
    if (idea.status !== 'proposed') return { error: 'no_aprobable', message: 'Solo se aprueba una idea «por decidir» (estado: ' + idea.status + ').' };
    return { resp: { ok: true, status: 'approved', message: 'Aprobada. Queda guardada para producción (no se publica ni programa sola).' }, writes: [row({ status: 'approved', decided_at: nowIso, decided_by: by, history: hist('aprobada') }, ['proposed'])] };
  }
  if (d === 'change') {
    const t = String(req.text || '').trim();
    if (t.length < 5) return { error: 'falta_cambio', message: 'Escribe qué cambiar (por ejemplo «otro ángulo» o «hazla más corta»).' };
    if (!['proposed', 'changed'].includes(idea.status)) return { error: 'no_cambiable', message: 'Esa idea ya no está por decidir (estado: ' + idea.status + ').' };
    return { resp: { ok: true, status: 'changed', message: 'Pedido guardado: Hermes la reescribe y vuelve a mostrártela.' }, writes: [row({ status: 'changed', change_request: t.slice(0, 1000), history: hist('cambio pedido', { text: t.slice(0, 300) }) }, ['proposed', 'changed'])] };
  }
  if (d === 'discard') {
    if (idea.status === 'discarded') return { resp: { ok: true, status: 'already_discarded', message: 'Ya estaba descartada.' }, writes: [] };
    if (!['proposed', 'changed', 'approved'].includes(idea.status)) return { error: 'no_descartable', message: 'Esa idea ya está en producción o publicada (estado: ' + idea.status + ').' };
    const chips = (Array.isArray(req.chips) ? req.chips : []).map((c) => String(c).slice(0, 40)).slice(0, 6);
    const reason = String(req.reason || '').trim().slice(0, 300) || null;
    return { resp: { ok: true, status: 'discarded', message: 'Descartada. La razón queda guardada para que Hermes aprenda.' },
      writes: [row({ status: 'discarded', decision_reason: reason, decision_chips: chips, decided_at: nowIso, decided_by: by, history: hist('descartada', { reason }) }, ['proposed', 'changed', 'approved']),
        { method: 'POST', path: 'learning_events', body: { type: 'idea_discard', subject_id: idea.id, before: { title: idea.title, channel: idea.channel, format: idea.format, hook: idea.hook, score: idea.score, origin: idea.origin }, after: null, reason: [chips.join(', '), reason].filter(Boolean).join(' — ') || null, by, is_test: Boolean(idea.is_test), created_at: nowIso }, prefer: 'return=minimal' }] };
  }
  if (d === 'move') {
    const w = String(req.week_start || '');
    if (!/^\d{4}-\d{2}-\d{2}$/.test(w) || new Date(w + 'T12:00:00Z').getUTCDay() !== 1) return { error: 'semana_invalida', message: 'Elige una semana válida (lunes).' };
    if (w < ideasMonday(now)) return { error: 'semana_pasada', message: 'No se puede mover a una semana que ya pasó.' };
    if (!['proposed', 'changed', 'approved'].includes(idea.status)) return { error: 'no_movible', message: 'Esa idea ya está en producción o publicada.' };
    if (w === idea.week_start) return { resp: { ok: true, status: 'unchanged', message: 'Ya estaba en esa semana.' }, writes: [] };
    return { resp: { ok: true, status: 'moved', message: 'Movida a la semana del ' + w + '.' }, writes: [row({ week_start: w, history: hist('movida', { from: idea.week_start, to: w }) }, ['proposed', 'changed', 'approved'])] };
  }
  return { error: 'decision_invalida', message: 'Decisión inválida: usa approve | change | discard | move.' };
}

function ideasDefaultMetric(objective, format) {
  const o = String(objective || '');
  if (o === 'autoridad' || o === 'alcance') return String(format || '') === 'reel' ? 'watch_time' : 'reach';
  if (o === 'educar') return 'saves';
  if (o === 'leads') return 'leads';
  if (o === 'recurso') return 'dms';
  if (o === 'conversaciones') return 'intent_comments';
  if (o === 'servicio') return 'profile_visits';
  return null;
}

function ideasEvidenceOk(row, known) {
  const k = known || {};
  const has = (list, id) => (Array.isArray(list) ? list : []).map((v) => String(v).toLowerCase()).includes(String(id).toLowerCase());
  return (row.evidence || []).some((e) => (e.type === 'source' && (k.sources || {})[String(e.id).toLowerCase()] === true) || (e.type === 'intel' && has(k.intel, e.id)) || (e.type === 'metric' && has(k.metrics, e.id)) || (e.type === 'resource' && has(k.resources, e.id)));
}

function ideasFicha(i) {
  const x = i || {};
  const has = (v) => typeof v === 'string' ? v.trim().length >= 3 : Boolean(v);
  const missing = [];
  if (!has(x.objective)) missing.push('objetivo');
  if (!has(x.audience_insight)) missing.push('público / insight');
  if (!has(x.hook)) missing.push('gancho');
  if (!has(x.core_message)) missing.push('idea central');
  if (!has(x.format)) missing.push('formato');
  if (!(Array.isArray(x.structure) && x.structure.filter((s) => has(typeof s === 'string' ? s : s && (s.text || s.title))).length >= 1)) missing.push('estructura / escenas');
  const pr = x.production || {};
  if (!(Array.isArray(pr.tools) && pr.tools.length) || !has(pr.how)) missing.push('cómo se produce');
  if (!has(x.effort)) missing.push('costo / esfuerzo');
  if (!has(x.risks)) missing.push('riesgos');
  if (!has(x.primary_metric)) missing.push('métrica principal');
  return { complete: missing.length === 0, missing };
}

function ideasGateView(d) {
  const now = Number(d && d.now) || Date.now();
  const C = ideasConfig();
  const week = ideasMonday(now + 7 * 86400000, d && d.tz);
  const ideas = Array.isArray(d && d.ideas_all) ? d.ideas_all : [];
  const since = ideasAddDays(week, -7 * C.dedupe_weeks);
  const recent = ideas.filter((i) => !i.is_test && i.week_start >= since).map((i) => ({ title: i.title, hook: i.hook || null, status: i.status, channel: i.channel, week_start: i.week_start }))
    .concat((Array.isArray(d && d.pieces) ? d.pieces : []).filter((p) => !p.is_test && Date.parse(p.created_at) >= now - 28 * 86400000).map((p) => ({ title: p.topic, hook: p.hook || null, status: 'pieza:' + p.status, channel: p.channel })));
  const already = ideas.filter((i) => !i.is_test && i.week_start === week && i.origin === 'hermes' && ['proposed', 'approved', 'changed'].includes(i.status)).length;
  const enabled = Boolean(d && d.content_cfg && d.content_cfg.ideas_enabled === true);
  const paused = Boolean(d && d.system_state && d.system_state.global_pause === true);
